9	/**
10	 * Rejects a create request whose last name and address already belong to an existing owner,
11	 * so the pair maps to a 409 — unless the request opts in with {@code sharesHousehold=true},
12	 * declaring that the two owners share a household. Comparison is by {@link HouseholdKey}, so
13	 * case and whitespace differences do not hide a collision.
14	 */
15	public class EnsureUniqueHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
20	            return;
21	        }
22	        String key = HouseholdKey.of(request.getLastName(), request.getAddress());
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (key.equals(HouseholdKey.of(existing.getLastName(), existing.getAddress()))) {
25	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
26	            }
27	        }
28	    }
29	}
