5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create request whose city already holds {@link #CAPACITY} or more owners, so the
11	 * request maps to a 409. Existing owners are counted case-insensitively on their trimmed city,
12	 * so incidental formatting differences neither hide nor inflate the count. Runs among the other
13	 * create guards, before {@link BuildOwner} maps the request to an entity.
14	 */
15	public class EnsureCityHasCapacity {
16	
17	    /** Maximum number of owners allowed to share a single city. */
18	    static final int CAPACITY = 50;
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws CityAtCapacityException {
22	        String city = normalize(request.getCity());
23	        int count = 0;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (city.equals(normalize(existing.getCity()))) {
26	                count++;
27	            }
28	        }
29	        if (count >= CAPACITY) {
30	            throw new CityAtCapacityException(request.getCity(), CAPACITY);
31	        }
32	    }
33	
34	    private static String normalize(String city) {
35	        return city == null ? "" : city.trim().toLowerCase();
36	    }
37	}
