9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Rejects a create request once {@link #DAILY_LIMIT} or more owners have already been
13	 * registered on the request's effective business day, so the request maps to a 429. Owners
14	 * are counted by their stored {@code registrationDate}, which is rolled forward onto a
15	 * business day on creation; this guard rolls the request's supplied-or-defaulted date the
16	 * same way (see {@link RegistrationDates}) so both sides count the same day. Runs among the
17	 * other create guards, before {@link BuildOwner} maps the request to an entity.
18	 */
19	public class EnsureDailyLimit {
20	
21	    /** Maximum number of owners allowed to be registered on a single business day. */
22	    static final int DAILY_LIMIT = 100;
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DailyLimitExceededException {
26	        LocalDate day = RegistrationDates.effective(request.getRegistrationDate());
27	        int count = 0;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (day.equals(existing.getRegistrationDate())) {
30	                count++;
31	            }
32	        }
33	        if (count >= DAILY_LIMIT) {
34	            throw new DailyLimitExceededException(day, DAILY_LIMIT);
35	        }
36	    }
37	}
