3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	
10	/**
11	 * Normalizes an optional email on an owner request. Email is not required: a null or blank
12	 * value is left untouched. When present it must be a syntactically valid address, otherwise
13	 * the request is rejected with {@link InvalidEmailException} (400). A valid address is stored
14	 * back on the shared {@code @Val} request lower-cased, so {@link BuildOwner}/{@link ApplyOwner}
15	 * and the response carry the canonical form.
16	 */
17	public class NormalizeOwnerEmail {
18	
19	    /** Local part and domain each a run of non-space, non-'@' characters, domain dotted. */
20	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
21	
22	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
23	        String raw = request.getEmail();
24	        if (raw == null || raw.isBlank()) {
25	            return;
26	        }
27	        String trimmed = raw.trim();
28	        if (!EMAIL.matcher(trimmed).matches()) {
29	            throw new InvalidEmailException(raw);
30	        }
31	        request.setEmail(trimmed.toLowerCase(Locale.ROOT));
32	    }
33	}
