1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's customer code before it is saved. The code is formatted
9	 * {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the upper-cased first three
10	 * letters of the city, {@code LAST3} the upper-cased first three letters of the last name
11	 * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
12	 * number of owners already in that city (e.g. {@code SYD-SMI-0007}). Runs after
13	 * {@link BuildOwner} has produced the entity and before {@link SaveOwner} persists it, so
14	 * {@code findAll()} sees only the owners that existed before this create; mutates the
15	 * built owner in place.
16	 */
17	public class AssignCustomerCode {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String city = owner.getCity();
21	        int sequence = countInCity(ownerRepository, city) + 1;
22	        owner.setCustomerCode(format(city, owner.getLastName(), sequence));
23	    }
24	
25	    private static int countInCity(OwnerRepository ownerRepository, String city) {
26	        int count = 0;
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (city.equalsIgnoreCase(existing.getCity())) {
29	                count++;
30	            }
31	        }
32	        return count;
33	    }
34	
35	    private static String format(String city, String lastName, int sequence) {
36	        return String.format("%s-%s-%04d", prefix(city), prefix(lastName), sequence);
37	    }
38	
39	    private static String prefix(String value) {
40	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
41	    }
42	}
